// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, new address[](0), new address[](0)); }
    function testFuzz_property(bytes4 queriedId) public {
        // Rule: any interface id that C claims to support implies C supports IERC165.
        bool claimsQueried = c.supportsInterface(queriedId);
        bool claimsErc165 = c.supportsInterface(type(IERC165).interfaceId);
        assertTrue(!claimsQueried || claimsErc165);
    }
}

interface IERC165 {
    function supportsInterface(bytes4 interfaceId) external view returns (bool);
}

