pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";
import {IERC165} from "../src/C_under_test.sol";
import {IAccessControl} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, new address[](0), new address[](0)); }

    function testFuzz_property(bytes4 interfaceId) public {
        bool reported = c.supportsInterface(interfaceId);
        bool isAC = interfaceId == type(IAccessControl).interfaceId;
