// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(0, new address[](0), new address[](0));
    }

    function testFuzz_property(address roleHolder, bytes32 role) public {
        // roleHolder defaults to the deployer (this contract), which received TIMELOCK_ADMIN_ROLE in setUp.
        vm.assume(roleHolder != address(0));

        bool adminHasDefault = c.hasRole(c.DEFAULT_ADMIN_ROLE(), roleHolder);
        bool holderHasRole = c.hasRole(role, roleHolder);
        bool otherHasRole = c.hasRole(role, address(0xdead));

        // Universal rule: hasRole agrees with actual membership, so the pair
        // (any non-member, any member-ish query) must NOT return identical values
        // for both a known member and a known non-member; i.e. hasRole for the
        // admin over DEFAULT_ADMIN_ROLE must be true while a fresh address must be false.
        assertTrue(
            adminHasDefault != otherHasRole || holderHasRole != otherHasRole,
            "hasRole must distinguish members from non-members"
        );
    }
}
